"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["45442"],{88578(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_valor_dominio.orientacao_tamanho","status":422,"titulo":"Tamanho da orienta\xe7\xe3o do valor de dom\xednio inv\xe1lido"},"descricao":{"codigo":"uniplus.configuracao.fato_valor_dominio.orientacao_tamanho","requisitos":[],"oQueAconteceu":["A orienta\xe7\xe3o enviada para um valor de fato do cat\xe1logo tem mais de 500 caracteres, ao acrescentar o valor (`POST /api/configuracao/admin/fatos-candidato/{id}/valores`) ou ao corrigi-lo (`PUT /api/configuracao/admin/fatos-candidato/{id}/valores/{codigo}`). A orienta\xe7\xe3o \xe9 o que o candidato l\xea abaixo da op\xe7\xe3o, em uma ou duas frases; os espa\xe7os nas pontas s\xe3o desconsiderados antes da confer\xeancia. Ela \xe9 opcional: sem orienta\xe7\xe3o, nada \xe9 recusado.","A recusa vem na lista `errors` da resposta, com `field` igual a `orientacao`. Se o corpo tiver outros problemas, cada um vem numa entrada pr\xf3pria da mesma resposta, e nada \xe9 gravado. A busca do fato vem antes da confer\xeancia do corpo, e na corre\xe7\xe3o a busca do valor tamb\xe9m: um `{id}` ou um `{codigo}` que n\xe3o existe responde como n\xe3o encontrado, e n\xe3o com esta recusa."],"comoResolver":["Reduza a orienta\xe7\xe3o a at\xe9 500 caracteres, ou deixe-a em branco."],"ondeAparece":["Acr\xe9scimo de um valor a um fato do cat\xe1logo","Corre\xe7\xe3o de um valor de um fato do cat\xe1logo"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato valor dominio"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"38e6e984f8a69f1cdfcd140295a410206c687849"}}')}}]);